  1	package gitrepo
  2	
  3	import (
  4		"errors"
  5		"fmt"
  6		"io/fs"
  7		"os"
  8		"path/filepath"
  9		"strings"
 10	)
 11	
 12	// ErrWorktreeMetadataNotFound reports that an explicit worktree root has no
 13	// .git entry. Repository opening uses it to distinguish a possible bare
 14	// repository from broken worktree metadata.
 15	var ErrWorktreeMetadataNotFound = errors.New("worktree Git metadata not found")
 16	
 17	// WorktreeMetadata contains Git directory facts for one explicit worktree
 18	// root. Paths are cleaned and absolute but retain their lexical spelling.
 19	type WorktreeMetadata struct {
 20		GitDir     string
 21		CommonDir  string
 22		WorktreeID string
 23	}
 24	
 25	// ResolveWorktreeMetadata resolves filesystem metadata for an explicit
 26	// worktree root. It does not discover a root, inspect Git environment
 27	// variables, run Git, cache results, or decide caller policy.
 28	func ResolveWorktreeMetadata(worktreeRoot string) (WorktreeMetadata, error) {
 29		if worktreeRoot == "" {
 30			return WorktreeMetadata{}, errors.New("worktree root is required")
 31		}
 32	
 33		root, err := filepath.Abs(worktreeRoot)
 34		if err != nil {
 35			return WorktreeMetadata{}, fmt.Errorf("resolve worktree root %q: %w", worktreeRoot, err)
 36		}
 37		root = filepath.Clean(root)
 38		if err := requireMetadataDirectory("worktree root", root); err != nil {
 39			return WorktreeMetadata{}, err
 40		}
 41	
 42		gitDirPath, err := resolveWorktreeGitDir(root)
 43		if err != nil {
 44			return WorktreeMetadata{}, err
 45		}
 46		commonDir, err := resolveWorktreeCommonDir(gitDirPath)
 47		if err != nil {
 48			return WorktreeMetadata{}, err
 49		}
 50		worktreeID, err := resolveWorktreeID(gitDirPath, commonDir)
 51		if err != nil {
 52			return WorktreeMetadata{}, err
 53		}
 54	
 55		return WorktreeMetadata{
 56			GitDir:     gitDirPath,
 57			CommonDir:  commonDir,
 58			WorktreeID: worktreeID,
 59		}, nil
 60	}
 61	
 62	func resolveWorktreeGitDir(worktreeRoot string) (string, error) {
 63		gitEntry := filepath.Join(worktreeRoot, gitDir)
 64		info, err := os.Lstat(gitEntry)
 65		if errors.Is(err, fs.ErrNotExist) {
 66			if rootErr := requireMetadataDirectory("worktree root", worktreeRoot); rootErr != nil {
 67				return "", rootErr
 68			}
 69			return "", fmt.Errorf("%w at %s: %w", ErrWorktreeMetadataNotFound, gitEntry, err)
 70		}
 71		if err != nil {
 72			return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
 73		}
 74		if info.Mode()&fs.ModeSymlink != 0 {
 75			info, err = os.Stat(gitEntry)
 76			if err != nil {
 77				return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
 78			}
 79		}
 80		if info.IsDir() {
 81			return gitEntry, nil
 82		}
 83		if !info.Mode().IsRegular() {
 84			return "", fmt.Errorf(".git entry at %s is neither a directory nor a regular file", gitEntry)
 85		}
 86	
 87		content, err := os.ReadFile(gitEntry) //nolint:gosec // path is anchored at the explicit worktree root.
 88		if err != nil {
 89			return "", fmt.Errorf("read .git file at %s: %w", gitEntry, err)
 90		}
 91		pointer, ok := strings.CutPrefix(strings.TrimRight(string(content), "\r\n"), "gitdir: ")
 92		if !ok {
 93			return "", fmt.Errorf("parse .git file at %s: missing gitdir prefix", gitEntry)
 94		}
 95		if pointer == "" {
 96			return "", fmt.Errorf("parse .git file at %s: empty gitdir value", gitEntry)
 97		}
 98	
 99		resolved, err := resolveMetadataDirectory("Git directory", worktreeRoot, pointer)
100		if err != nil {
101			return "", err
102		}
103		return resolved, nil
104	}
105	
106	func resolveWorktreeCommonDir(gitDirPath string) (string, error) {
107		commonFile := filepath.Join(gitDirPath, "commondir")
108		info, err := os.Lstat(commonFile)
109		if errors.Is(err, fs.ErrNotExist) {
110			return gitDirPath, nil
111		}
112		if err != nil {
113			return "", fmt.Errorf("inspect commondir file at %s: %w", commonFile, err)
114		}
115		if !info.Mode().IsRegular() {
116			return "", fmt.Errorf("commondir entry at %s is not a regular file", commonFile)
117		}
118	
119		content, err := os.ReadFile(commonFile) //nolint:gosec // path is inside the validated per-worktree Git directory.
120		if err != nil {
121			return "", fmt.Errorf("read commondir file at %s: %w", commonFile, err)
122		}
123		pointer := strings.TrimRight(string(content), "\r\n")
124		if pointer == "" {
125			return "", fmt.Errorf("parse commondir file at %s: empty value", commonFile)
126		}
127	
128		resolved, err := resolveMetadataDirectory("common Git directory", gitDirPath, pointer)
129		if err != nil {
130			return "", err
131		}
132		return resolved, nil
133	}
134	
135	func resolveWorktreeID(gitDirPath, commonDir string) (string, error) {
136		same, err := metadataDirectoriesIdentifySameFile(gitDirPath, commonDir)
137		if err != nil {
138			return "", fmt.Errorf("compare Git and common directories: %w", err)
139		}
140		if same {
141			return "", nil
142		}
143	
144		registrationRoot := filepath.Join(commonDir, "worktrees")
145		registrationPath := gitDirPath
146		same, err = metadataDirectoriesIdentifySameFile(filepath.Dir(registrationPath), registrationRoot)
147		if err != nil {
148			return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
149		}
150		if !same {
151			registrationPath, err = filepath.EvalSymlinks(gitDirPath)
152			if err != nil {
153				return "", fmt.Errorf("resolve linked-worktree registration %s: %w", gitDirPath, err)
154			}
155			same, err = metadataDirectoriesIdentifySameFile(filepath.Dir(registrationPath), registrationRoot)
156			if err != nil {
157				return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
158			}
159			if !same {
160				return "", fmt.Errorf("git directory %s is not an immediate child of %s", gitDirPath, registrationRoot)
161			}
162		}
163	
164		id := filepath.Base(registrationPath)
165		if id == "." || id == string(filepath.Separator) || id == "" {
166			return "", fmt.Errorf("git directory %s has no worktree registration name", gitDirPath)
167		}
168		return id, nil
169	}
170	
171	// Preserve the pointer spelling until validation so a missing component cannot
172	// disappear through lexical cleaning before the filesystem sees it.
173	func resolveMetadataPath(base, value string) string {
174		if filepath.IsAbs(value) {
175			return value
176		}
177		return base + string(filepath.Separator) + value
178	}
179	
180	func resolveMetadataDirectory(label, base, value string) (string, error) {
181		resolved := resolveMetadataPath(base, value)
182		if err := requireMetadataDirectory(label, resolved); err != nil {
183			return "", err
184		}
185	
186		cleaned := filepath.Clean(resolved)
187		if cleaned == resolved {
188			return cleaned, nil
189		}
190		// Cleaning a path through a symlink before resolving ".." can change which
191		// directory it names, so keep the lexical result only when identity agrees.
192		if same, err := metadataDirectoriesIdentifySameFile(resolved, cleaned); err == nil && same {
193			return cleaned, nil
194		}
195	
196		physical, err := filepath.EvalSymlinks(resolved)
197		if err != nil {
198			return "", fmt.Errorf("resolve %s at %s: %w", label, resolved, err)
199		}
200		return filepath.Clean(physical), nil
201	}
202	
203	func requireMetadataDirectory(label, path string) error {
204		info, err := os.Stat(path) //nolint:gosec // the explicit-root API resolves caller-selected repository metadata.
205		if err != nil {
206			return fmt.Errorf("inspect %s at %s: %w", label, path, err)
207		}
208		if !info.IsDir() {
209			return fmt.Errorf("%s at %s is not a directory", label, path)
210		}
211		return nil
212	}
213	
214	func metadataDirectoriesIdentifySameFile(a, b string) (bool, error) {
215		aInfo, err := os.Stat(a) //nolint:gosec // explicit-root metadata paths are validated before identity comparison.
216		if err != nil {
217			return false, fmt.Errorf("inspect %s: %w", a, err)
218		}
219		if !aInfo.IsDir() {
220			return false, fmt.Errorf("%s is not a directory", a)
221		}
222		bInfo, err := os.Stat(b)
223		if err != nil {
224			return false, fmt.Errorf("inspect %s: %w", b, err)
225		}
226		if !bInfo.IsDir() {
227			return false, fmt.Errorf("%s is not a directory", b)
228		}
229		return os.SameFile(aInfo, bInfo), nil
230	}
  1	package gitrepo
  2	
  3	import (
  4		"context"
  5		"errors"
  6		"fmt"
  7		"os"
  8		"path/filepath"
  9		"strings"
 10	
 11		"github.com/entireio/cli/cmd/entire/cli/paths"
 12	
 13		"github.com/go-git/go-billy/v6"
 14		"github.com/go-git/go-billy/v6/osfs"
 15		"github.com/go-git/go-git/v6"
 16		"github.com/go-git/go-git/v6/plumbing/cache"
 17		gitfilesystem "github.com/go-git/go-git/v6/storage/filesystem"
 18		"github.com/go-git/go-git/v6/storage/filesystem/dotgit"
 19	)
 20	
 21	const gitDir = ".git"
 22	
 23	// sharedObjectCache is one process-wide object cache. go-git uses the cache
 24	// passed to the storage as its delta-base cache, so a per-open cache makes
 25	// every open re-read pack data from scratch.
 26	var sharedObjectCache = cache.NewObjectLRUDefault()
 27	
 28	// OpenCurrent opens the current git worktree with object alternates enabled.
 29	// The caller owns the returned repository and must close it.
 30	//
 31	// A worktree root that will not resolve is an error, not a reason to open the
 32	// current directory. This used to fall back to ".", which is a different
 33	// repository whenever the two disagree, and go-git disagrees with git in exactly
 34	// the cases that made the resolution fail:
 35	//
 36	//   - git exports GIT_DIR and GIT_WORK_TREE to the hooks it runs, and
 37	//     paths.WorktreeRoot honours them. OpenPath(".") cannot see them, so a hook
 38	//     running for repo A whose git lookup failed opened repo B, the unrelated
 39	//     repository it happened to be sitting in. Verified.
 40	//   - git refuses a repository whose ownership fails its safe.directory check,
 41	//     and refuses a .git it cannot parse. go-git applies neither check, so the
 42	//     fallback opened repositories the user's own git declines to touch.
 43	//
 44	// Five of the six callers write through the repository they are handed, and all
 45	// five sit behind the root pre-run, which already refuses to run when the
 46	// worktree root does not resolve — so this closes a trap rather than a live bug.
 47	// The sixth is a best-effort advisory that genuinely wants the old behaviour and
 48	// now asks for it by name: see OpenCurrentOrCwd.
 49	func OpenCurrent(ctx context.Context) (*git.Repository, error) {
 50		repoRoot, err := paths.WorktreeRoot(ctx)
 51		if err != nil {
 52			return nil, fmt.Errorf("resolve worktree root: %w", err)
 53		}
 54		return OpenPath(repoRoot)
 55	}
 56	
 57	// OpenCurrentOrCwd is OpenCurrent with the current directory as a fallback when
 58	// the worktree root will not resolve.
 59	//
 60	// It exists for one caller, WarnCheckpointPolicyIfNeeded, and the properties
 61	// that make it acceptable there do not generalise: it is dispatched from
 62	// main.go after cobra has finished, so unlike every other repository open it has
 63	// no pre-run guard in front of it; it only READS a policy ref to decide whether
 64	// to print an advisory line; and it discards every error it gets. Opening the
 65	// wrong repository there costs a warning that is skipped or shown, not a write
 66	// that lands in the wrong place.
 67	//
 68	// Do not reach for this because OpenCurrent started returning an error. That
 69	// error means Entire could not establish which repository this is, and for
 70	// anything that writes, stopping is the whole point.
 71	func OpenCurrentOrCwd(ctx context.Context) (*git.Repository, error) {
 72		if repo, err := OpenCurrent(ctx); err == nil {
 73			return repo, nil
 74		}
 75		return OpenPath(".")
 76	}
 77	
 78	// OpenPath opens a git repository with object alternates enabled.
 79	// The caller owns the returned repository and must close it.
 80	func OpenPath(repoRoot string) (*git.Repository, error) {
 81		repoRoot, err := filepath.Abs(repoRoot)
 82		if err != nil {
 83			return nil, fmt.Errorf("resolve repository root: %w", err)
 84		}
 85		repoRoot = filepath.Clean(repoRoot)
 86	
 87		metadata, err := ResolveWorktreeMetadata(repoRoot)
 88		if err != nil {
 89			if errors.Is(err, ErrWorktreeMetadataNotFound) {
 90				repo, bareErr := openBareRepository(repoRoot)
 91				if bareErr == nil {
 92					return repo, nil
 93				}
 94				return nil, fmt.Errorf(
 95					"failed to open repository at %s: worktree metadata: %w; bare repository validation: %w",
 96					repoRoot,
 97					err,
 98					bareErr,
 99				)
100			}
101			return nil, fmt.Errorf("failed to open repository: resolve worktree metadata: %w", err)
102		}
103	
104		repo, err := openWorktreeRepository(repoRoot, metadata)
105		if err == nil {
106			return repo, nil
107		}
108	
109		hasAlternates, alternatesErr := hasObjectAlternates(metadata)
110		if alternatesErr != nil {
111			return nil, fmt.Errorf("inspect repository after specialized open failed: %w", alternatesErr)
112		}
113		usesReftable, reftableErr := inspectRepoUsesReftable(metadata.GitDir, metadata.CommonDir)
114		if reftableErr != nil {
115			return nil, fmt.Errorf("inspect repository after specialized open failed: %w", reftableErr)
116		}
117		if hasAlternates || usesReftable {
118			return nil, fmt.Errorf("failed to open repository with specialized storage: %w", err)
119		}
120	
121		// PlainOpen is safe only after complete metadata validation and positive
122		// evidence that neither specialized storage feature is present.
123		if fallbackRepo, fallbackErr := git.PlainOpen(repoRoot); fallbackErr == nil {
124			return fallbackRepo, nil
125		}
126		return nil, fmt.Errorf("failed to open repository: %w", err)
127	}
128	
129	// ResolveDotGitPath resolves the .git entry for a worktree without opening the
130	// repository. Callers that need Git metadata should use this shared resolver.
131	func ResolveDotGitPath(repoRoot string) (string, error) {
132		return resolveDotGitPath(repoRoot)
133	}
134	
135	// ResolveCommonGitPath resolves the shared Git directory for a resolved .git
136	// directory. An empty result means the repository has no commondir file.
137	func ResolveCommonGitPath(dotGitPath string) (string, error) {
138		return resolveCommonGitPath(dotGitPath)
139	}
140	
141	func openBareRepository(repoRoot string) (*git.Repository, error) {
142		repo, err := git.PlainOpen(repoRoot)
143		if err != nil {
144			return nil, fmt.Errorf("failed to open repository: %w", err)
145		}
146		config, err := repo.Config()
147		if err != nil {
148			_ = repo.Close()
149			return nil, fmt.Errorf("validate bare repository config: %w", err)
150		}
151		if !config.Core.IsBare {
152			_ = repo.Close()
153			return nil, fmt.Errorf("path %s has no worktree metadata and is not a bare repository", repoRoot)
154		}
155		return repo, nil
156	}
