158	func hasObjectAlternates(metadata WorktreeMetadata) (bool, error) {
159		candidates := []string{filepath.Join(metadata.GitDir, "objects", "info", "alternates")}
160		if metadata.CommonDir != metadata.GitDir {
161			candidates = append(candidates, filepath.Join(metadata.CommonDir, "objects", "info", "alternates"))
162		}
163		for _, candidate := range candidates {
164			info, err := os.Lstat(candidate)
165			if err == nil {
166				if info.Mode()&os.ModeSymlink != 0 {
167					if _, err := os.Stat(candidate); err != nil {
168						return false, fmt.Errorf("inspect alternates file: %w", err)
169					}
170				}
171				return true, nil
172			}
173			if !errors.Is(err, os.ErrNotExist) {
174				return false, fmt.Errorf("inspect alternates file: %w", err)
175			}
176		}
177		return false, nil
178	}
179	
180	func openWorktreeRepository(repoRoot string, metadata WorktreeMetadata) (*git.Repository, error) {
181		// Wrap the git-dir filesystems so relative alternate object directories are
182		// rewritten to absolute paths on read; go-git cannot follow relative
183		// alternates on its own. The alternates file lives under the common git dir
184		// for linked worktrees, so wrap both.
185		dotGitFS := wrapAlternatesRewrite(osfs.New(metadata.GitDir, osfs.WithBoundOS()))
186		var commonGitFS billy.Filesystem
187		if metadata.CommonDir != metadata.GitDir {
188			commonGitFS = wrapAlternatesRewrite(osfs.New(metadata.CommonDir, osfs.WithBoundOS()))
189		}
190	
191		repositoryFS := dotgit.NewRepositoryFilesystem(dotGitFS, commonGitFS)
192		// Shared clones write absolute object directories to objects/info/alternates;
193		// an OS-rooted filesystem lets go-git follow those paths outside .git.
194		storage := gitfilesystem.NewStorageWithOptions(
195			repositoryFS,
196			sharedObjectCache,
197			gitfilesystem.Options{
198				AlternatesFS: newAlternatesFilesystem(),
199			},
200		)
201	
202		// go-git's filesystem storer cannot read the reftable ref backend: it reads
203		// refs from .git/refs, packed-refs and .git/HEAD, none of which are
204		// authoritative in a reftable repository, and its extension check rejects
205		// extensions.refstorage=reftable outright. Route ref operations through the
206		// git CLI for such repositories while keeping object storage on go-git.
207		//
208		// TODO: drop the reftable branch below and the whole reftableStorer
209		// (reftable.go) once go-git ships a native reftable reader/writer. At that
210		// point a plain git.Open(storage, worktreeFS) will handle reftable
211		// repositories directly and this CLI-backed shim is dead weight.
212		worktreeFS := osfs.New(repoRoot, osfs.WithBoundOS())
213		usesReftable, err := inspectRepoUsesReftable(metadata.GitDir, metadata.CommonDir)
214		if err != nil {
215			_ = storage.Close()
216			return nil, err
217		}
218		if usesReftable {
219			repo, err := git.Open(newReftableStorer(storage, metadata.GitDir), worktreeFS)
220			if err != nil {
221				_ = storage.Close()
222				return nil, fmt.Errorf("open reftable repository storage: %w", err)
223			}
224			return repo, nil
225		}
226	
227		repo, err := git.Open(storage, worktreeFS)
228		if err != nil {
229			_ = storage.Close()
230			return nil, fmt.Errorf("open repository storage: %w", err)
231		}
232		return repo, nil
233	}
234	
235	func resolveDotGitPath(repoRoot string) (string, error) {
236		gitPath := filepath.Join(repoRoot, gitDir)
237		info, err := os.Stat(gitPath)
238		if err != nil {
239			return "", fmt.Errorf("stat .git path: %w", err)
240		}
241		if info.IsDir() {
242			return gitPath, nil
243		}
244	
245		content, err := os.ReadFile(gitPath) //nolint:gosec // gitPath is resolved from the git worktree root.
246		if err != nil {
247			return "", fmt.Errorf("read .git file: %w", err)
248		}
249	
250		line, _, _ := strings.Cut(string(content), "\n")
251		gitdir, ok := strings.CutPrefix(strings.TrimSpace(line), "gitdir:")
252		if !ok {
253			return "", errors.New(".git file has no gitdir prefix")
254		}
255	
256		gitdir = strings.TrimSpace(gitdir)
257		if filepath.IsAbs(gitdir) {
258			return filepath.Clean(gitdir), nil
259		}
260		return filepath.Clean(filepath.Join(repoRoot, gitdir)), nil
261	}
262	
263	func resolveCommonGitPath(dotGitPath string) (string, error) {
264		content, err := os.ReadFile(filepath.Join(dotGitPath, "commondir")) //nolint:gosec // dotGitPath is resolved from the git worktree root.
265		if errors.Is(err, os.ErrNotExist) {
266			return "", nil
267		}
268		if err != nil {
269			return "", fmt.Errorf("read commondir file: %w", err)
270		}
271	
272		commonPath := strings.TrimSpace(string(content))
273		if commonPath == "" {
274			return "", nil
275		}
276		if filepath.IsAbs(commonPath) {
277			return filepath.Clean(commonPath), nil
278		}
279		return filepath.Clean(filepath.Join(dotGitPath, commonPath)), nil
280	}
