 21	// reftableGitTimeout bounds each git plumbing invocation the reftable storer
 22	// makes. Ref reads/writes against the local reftable stack are fast; the
 23	// timeout only guards against a wedged git process.
 24	const reftableGitTimeout = 30 * time.Second
 25	
 26	// inspectRepoUsesReftable reports whether the repository at the given git directories
 27	// stores its references using the reftable backend rather than the classic
 28	// loose-files + packed-refs layout.
 29	//
 30	// go-git (through the vendored v6 alpha) has no reftable reader: its filesystem
 31	// storer reads refs from .git/refs, .git/packed-refs and .git/HEAD, none of
 32	// which are authoritative in a reftable repository. Detection lets us route ref
 33	// operations through the git CLI instead (see reftableStorer).
 34	//
 35	// A reftable repository is identified by the presence of a "reftable/"
 36	// directory under either the worktree git dir or the common git dir. Git 2.45+
 37	// creates this directory for `git init --ref-format=reftable` and for
 38	// `git refs migrate --ref-format=reftable`. Checking the directory avoids
 39	// parsing config and works for linked worktrees, where the shared stack lives
 40	// under the common git dir.
 41	func inspectRepoUsesReftable(dotGitPath, commonGitPath string) (bool, error) {
 42		candidates := []string{filepath.Join(dotGitPath, "reftable")}
 43		if commonGitPath != "" && commonGitPath != dotGitPath {
 44			candidates = append(candidates, filepath.Join(commonGitPath, "reftable"))
 45		}
 46		for _, dir := range candidates {
 47			// Lstat, not Stat: git creates reftable/ as a real directory, so a
 48			// symlink in its place is not a genuine reftable stack. Lstat inspects
 49			// the entry itself rather than following the link, so a symlink reports
 50			// IsDir()==false and is correctly not treated as a reftable repository.
 51			info, err := os.Lstat(dir)
 52			if err == nil {
 53				if info.IsDir() {
 54					return true, nil
 55				}
 56				continue
 57			}
 58			if !errors.Is(err, os.ErrNotExist) {
 59				return false, fmt.Errorf("inspect reftable directory %s: %w", dir, err)
 60			}
 61		}
 62		return false, nil
 63	}
 64	
 65	// reftableStorer adapts a filesystem-backed go-git storage so it can open and
 66	// operate on repositories that use the reftable ref backend. Object, config,
 67	// index, shallow and module storage keep flowing through the embedded
 68	// filesystem storage (reftable only changes ref storage, not object storage);
 69	// the reference-storer methods are overridden to shell out to the git CLI,
 70	// which is the only reftable reader/writer available to us.
 71	//
 72	// It also advertises reftable support via the ExtensionChecker interface so
 73	// go-git's extension verification does not reject the repository on open.
 74	//
 75	// TODO: remove this entire type (and its wiring in repository.go) once go-git
 76	// gains a built-in reftable reader/writer. It exists only because the vendored
 77	// go-git has no reftable backend, so ref operations must shell out to the git
 78	// CLI. When upstream supports reftable natively, the plain filesystem storer
 79	// handles these repositories and this shim can be deleted.
 80	type reftableStorer struct {
 81		*gitfilesystem.Storage
 82	
 83		gitDir string
 84	
 85		// runGitFn runs a git plumbing command and returns trimmed stdout, raw
 86		// stderr, and the exec error. It is overridable in tests to simulate
 87		// spawn/timeout/exit failures deterministically; in production it is nil and
 88		// runGit dispatches to execGit.
 89		runGitFn func(args ...string) (string, []byte, error)
 90	}
 91	
 92	var (
 93		_ gogitstorage.Storer = (*reftableStorer)(nil)
 94		// The concrete methods below satisfy storer.ReferenceStorer, overriding the
 95		// embedded filesystem implementation.
 96		_ storer.ReferenceStorer = (*reftableStorer)(nil)
 97	)
 98	
 99	// newReftableStorer wraps a filesystem storage with reftable-aware reference
100	// handling. gitDir must be the repository's git directory (for a linked
101	// worktree, the worktree's git dir); git resolves the shared reftable stack
102	// from its commondir automatically.
103	func newReftableStorer(fs *gitfilesystem.Storage, gitDir string) *reftableStorer {
104		return &reftableStorer{Storage: fs, gitDir: gitDir}
105	}
106	
107	// SupportsExtension lets go-git open a repository that declares the
108	// extensions.refstorage=reftable extension, and preserves the embedded
109	// filesystem storage's support for every other extension it recognises
110	// (objectformat=sha1/sha256, worktreeconfig).
111	//
112	// Defining this method here shadows the promoted *gitfilesystem.Storage
113	// method, so it must delegate: without the fallback, a reftable repository
114	// that also declares objectformat=sha256 or worktreeConfig would be rejected
115	// by go-git's extension verification with ErrUnknownExtension, since it only
116	// consults the storer's SupportsExtension. Reftable only changes ref storage,
117	// not object storage, so object-format support is unaffected.
118	func (s *reftableStorer) SupportsExtension(name, value string) bool {
119		if strings.EqualFold(name, "refstorage") {
120			return true
121		}
122		return s.Storage.SupportsExtension(name, value)
123	}
124	
125	// runGit runs a git plumbing command scoped to this repository's git dir and
126	// returns trimmed stdout, raw stderr, and the exec error. Only ref plumbing
127	// (for-each-ref, symbolic-ref, update-ref, rev-parse) is used, none of which
128	// trigger git hooks, so this cannot recurse back into entire. Tests may inject
129	// runGitFn to simulate failures; production dispatches to execGit.
130	func (s *reftableStorer) runGit(args ...string) (string, []byte, error) {
131		if s.runGitFn != nil {
132			return s.runGitFn(args...)
133		}
134		return s.execGit(args...)
135	}
136	
137	func (s *reftableStorer) execGit(args ...string) (string, []byte, error) {
138		ctx, cancel := context.WithTimeout(context.Background(), reftableGitTimeout)
139		defer cancel()
140	
141		full := append([]string{"--git-dir", s.gitDir}, args...)
142		cmd := exec.CommandContext(ctx, "git", full...)
143		cmd.Env = gitPlumbingEnv()
144	
145		var stdout, stderr bytes.Buffer
146		cmd.Stdout = &stdout
147		cmd.Stderr = &stderr
148		err := cmd.Run()
149		// On our timeout the process is killed and Run reports the kill as an
150		// *exec.ExitError, which would be indistinguishable from a genuine
151		// non-zero exit. Re-wrap with the context error so callers (refLookupAbsent)
152		// never mistake a wedged git for a definitive "ref not found".
153		if err != nil && ctx.Err() != nil {
154			err = fmt.Errorf("git %s timed out after %s: %w", strings.Join(args, " "), reftableGitTimeout, ctx.Err())
155		}
156		return strings.TrimRight(stdout.String(), "\n"), stderr.Bytes(), err
157	}
158	
159	// gitPlumbingEnv builds the environment for a reftable git plumbing command.
160	// LC_ALL=C / LANG=C force untranslated (English) diagnostics so the stderr
161	// classification (isRefCASConflict, and RemoveReference's idempotency check)
162	// stays correct on a localized machine — git's error messages are i18n'd, and
163	// matching translated text would silently misclassify CAS conflicts and delete
164	// failures. GIT_TERMINAL_PROMPT=0 keeps git non-interactive. The forced values
165	// are appended last so they override anything the caller's environment set
166	// (os/exec keeps the last value for a duplicate key). Mirrors the sibling
167	// shell-out in checkpoint/shadow_ref.go.
168	func gitPlumbingEnv() []string {
169		return append(os.Environ(),
170			"GIT_TERMINAL_PROMPT=0",
171			"LC_ALL=C",
172			"LANG=C",
173		)
174	}
175	
176	// refLookupAbsent reports whether a failed ref lookup (rev-parse --verify
177	// --quiet, update-ref) means the reference is genuinely absent rather than a
178	// failure to consult git at all. Only genuine absence may map to the
179	// plumbing.ErrReferenceNotFound / idempotent-delete sentinels; a spawn failure,
180	// timeout, or I/O error must be surfaced so a transient git failure is never
181	// mistaken for a missing ref (which would let the strategy orphan a checkpoint
182	// ref or drop a link).
183	//
184	// git ran and reported absence iff it exited non-zero AND stayed silent: under
185	// --quiet a missing ref produces no error output, whereas a fatal/I/O failure
186	// exits non-zero with a "fatal: ..." message, and a spawn failure or our
187	// timeout is not an *exec.ExitError at all.
188	func refLookupAbsent(err error, stderr []byte) bool {
189		if err == nil {
190			return false
191		}
192		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
193			return false
194		}
195		var exitErr *exec.ExitError
196		if !errors.As(err, &exitErr) {
197			return false
198		}
199		return len(bytes.TrimSpace(stderr)) == 0
200	}
201	
202	// SetReference stores a reference, dispatching to symbolic-ref for symbolic
203	// references and update-ref for hash references.
204	func (s *reftableStorer) SetReference(ref *plumbing.Reference) error {
205		if ref == nil {
206			return nil
207		}
208		if ref.Type() == plumbing.SymbolicReference {
209			if _, stderr, err := s.runGit("symbolic-ref", "--end-of-options", ref.Name().String(), ref.Target().String()); err != nil {
210				return fmt.Errorf("reftable set symbolic ref %s: %s: %w", ref.Name(), strings.TrimSpace(string(stderr)), err)
211			}
212			return nil
213		}
214		if _, stderr, err := s.runGit("update-ref", "--end-of-options", ref.Name().String(), ref.Hash().String()); err != nil {
215			return fmt.Errorf("reftable set ref %s: %s: %w", ref.Name(), strings.TrimSpace(string(stderr)), err)
216		}
217		return nil
218	}
219	
220	// CheckAndSetReference performs a compare-and-swap update. When old is non-nil
221	// the update is conditioned on the current value, mirroring go-git's atomic
222	// semantics; a genuine mismatch is reported as storage.ErrReferenceHasChanged.
223	//
224	// Only a real compare-and-swap conflict maps to that sentinel. Callers such as
225	// strategy.atomicSetV1Ref treat ErrReferenceHasChanged as "another worktree
226	// advanced the ref" and abort the push as a concurrency event, while wrapping
227	// every other error as a genuine failure. Mapping an unrelated failure (bad
228	// object, invalid ref name, lock contention, timeout, git spawn failure) to the
229	// conflict sentinel would misreport a storage error as a benign race, so those
230	// are surfaced as themselves.
231	func (s *reftableStorer) CheckAndSetReference(newRef, old *plumbing.Reference) error {
232		if newRef == nil {
233			return nil
234		}
235		if newRef.Type() == plumbing.SymbolicReference {
236			// Symbolic refs (e.g. HEAD) have no CAS form in update-ref; set directly.
237			return s.SetReference(newRef)
238		}
239		if old == nil {
240			return s.SetReference(newRef)
241		}
242		_, stderr, err := s.runGit("update-ref", "--end-of-options", newRef.Name().String(), newRef.Hash().String(), old.Hash().String())
243		if err == nil {
244			return nil
245		}
246		if isRefCASConflict(stderr) {
247			return gogitstorage.ErrReferenceHasChanged
248		}
249		return fmt.Errorf("reftable CAS ref %s: %s: %w", newRef.Name(), strings.TrimSpace(string(stderr)), err)
250	}
251	
252	// isRefCASConflict reports whether git update-ref stderr indicates a
253	// compare-and-swap conflict: the stored value was not the expected old value
254	// ("... is at X but expected Y"), or a create-if-absent update found the ref
255	// already present ("reference already exists"). These are the only failures
256	// that mean the reference changed concurrently. Object/name/lock/spawn errors
257	// carry different messages and must not be misclassified as conflicts.
258	func isRefCASConflict(stderr []byte) bool {
259		msg := strings.ToLower(string(stderr))
260		return strings.Contains(msg, "but expected") ||
261			strings.Contains(msg, "reference already exists")
262	}
263	
264	// Reference returns the reference with the given name, preserving symbolic refs
265	// (such as HEAD) so go-git can resolve them itself.
266	func (s *reftableStorer) Reference(name plumbing.ReferenceName) (*plumbing.Reference, error) {
267		// Symbolic refs: symbolic-ref exits 0 and prints the target only for a
268		// genuine symbolic ref; -q makes it exit non-zero silently for a non-symbolic
269		// name. Classify the probe failure the same way as elsewhere: a genuine "not
270		// a symbolic ref" (exit non-zero, empty stderr) falls through to the hash
271		// lookup, but a spawn/timeout/I-O failure is surfaced rather than silently
272		// downgrading a symbolic ref (e.g. HEAD on a branch) to a Hash reference
273		// named "HEAD", which would make callers read the repo as detached.
274		target, symStderr, symErr := s.runGit("symbolic-ref", "-q", "--end-of-options", name.String())
275		switch {
276		case symErr == nil && target != "":
277			return plumbing.NewSymbolicReference(name, plumbing.ReferenceName(target)), nil
278		case symErr != nil && !refLookupAbsent(symErr, symStderr):
279			return nil, fmt.Errorf("reftable probe symbolic ref %s: %s: %w", name, strings.TrimSpace(string(symStderr)), symErr)
280		}
281	
282		// Hash refs: rev-parse --verify resolves the ref to the object it points at.
283		// "^0" would peel tags; we want the ref's direct target, so verify the name
284		// as-is. A non-existent ref exits non-zero silently.
285		out, stderr, err := s.runGit("rev-parse", "--verify", "--quiet", "--end-of-options", name.String())
286		if err != nil {
287			if refLookupAbsent(err, stderr) {
288				return nil, plumbing.ErrReferenceNotFound
289			}
290			return nil, fmt.Errorf("reftable resolve ref %s: %s: %w", name, strings.TrimSpace(string(stderr)), err)
291		}
292		if out == "" {
293			return nil, plumbing.ErrReferenceNotFound
294		}
295		h := plumbing.NewHash(out)
296		if h.IsZero() {
297			return nil, plumbing.ErrReferenceNotFound
298		}
299		return plumbing.NewHashReference(name, h), nil
300	}
301	
302	// IterReferences returns an iterator over every reference in the repository,
303	// including HEAD, matching the behaviour of the filesystem storer.
304	func (s *reftableStorer) IterReferences() (storer.ReferenceIter, error) {
305		refs := make([]*plumbing.Reference, 0, 16)
306	
307		// HEAD (symbolic on a branch, detached hash otherwise) is not emitted by
308		// for-each-ref, so resolve it explicitly first, classifying each probe:
309		// a genuine "not symbolic" (exit non-zero, empty stderr) means HEAD is
310		// detached, so resolve it as a hash; a spawn/timeout/I-O failure is surfaced
311		// rather than silently dropping HEAD or downgrading a symbolic HEAD to a
312		// hash; and a genuinely absent HEAD (unborn/empty repo) is omitted, matching
313		// the filesystem storer.
314		headTarget, headSymStderr, headSymErr := s.runGit("symbolic-ref", "-q", "--end-of-options", "HEAD")
315		switch {
316		case headSymErr == nil && headTarget != "":
317			refs = append(refs, plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.ReferenceName(headTarget)))
318		case headSymErr != nil && !refLookupAbsent(headSymErr, headSymStderr):
319			return nil, fmt.Errorf("reftable probe HEAD symbolic ref: %s: %w", strings.TrimSpace(string(headSymStderr)), headSymErr)
320		default:
321			// HEAD is detached or genuinely not symbolic: resolve it as a hash.
322			out, stderr, headErr := s.runGit("rev-parse", "--verify", "--quiet", "--end-of-options", "HEAD")
323			switch {
324			case headErr == nil && out != "":
325				if h := plumbing.NewHash(out); !h.IsZero() {
326					refs = append(refs, plumbing.NewHashReference(plumbing.HEAD, h))
327				}
328			case headErr != nil && !refLookupAbsent(headErr, stderr):
329				return nil, fmt.Errorf("reftable resolve HEAD: %s: %w", strings.TrimSpace(string(stderr)), headErr)
330			}
331		}
332	
333		// All refs under refs/. %(symref) is non-empty only for symbolic refs so we
334		// preserve their symbolic nature (e.g. refs/remotes/origin/HEAD).
335		out, stderr, err := s.runGit("for-each-ref", "--format=%(objectname) %(refname) %(symref)")
336		if err != nil {
337			return nil, fmt.Errorf("reftable iterate refs: %s: %w", strings.TrimSpace(string(stderr)), err)
338		}
339		scanner := bufio.NewScanner(strings.NewReader(out))
340		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
341		for scanner.Scan() {
342			line := scanner.Text()
343			if strings.TrimSpace(line) == "" {
344				continue
345			}
346			fields := strings.SplitN(line, " ", 3)
347			if len(fields) < 2 {
348				continue
349			}
350			objectName, refName := fields[0], fields[1]
351			symref := ""
352			if len(fields) == 3 {
353				symref = strings.TrimSpace(fields[2])
354			}
355			if symref != "" {
356				refs = append(refs, plumbing.NewSymbolicReference(plumbing.ReferenceName(refName), plumbing.ReferenceName(symref)))
357				continue
358			}
359			h := plumbing.NewHash(objectName)
360			if h.IsZero() {
361				continue
362			}
363			refs = append(refs, plumbing.NewHashReference(plumbing.ReferenceName(refName), h))
364		}
365		if err := scanner.Err(); err != nil {
366			return nil, fmt.Errorf("reftable scan refs: %w", err)
367		}
368	
369		return storer.NewReferenceSliceIter(refs), nil
370	}
371	
372	// RemoveReference deletes a reference. Deleting a missing ref is treated as a
373	// success so callers can remove idempotently, matching go-git's semantics.
374	func (s *reftableStorer) RemoveReference(name plumbing.ReferenceName) error {
375		// A symbolic ref must be deleted with symbolic-ref -d; update-ref -d on a
376		// symbolic ref deletes the ref it points at instead (e.g. update-ref -d HEAD
377		// deletes the current branch). The symbolic-ref -q probe reports absence the
378		// same way as a lookup — exit non-zero with empty stderr — so classify its
379		// failure: only a genuine "not a symbolic ref / not found" may fall through
380		// to update-ref -d. A spawn/timeout/I-O failure must be surfaced rather than
381		// assumed non-symbolic, or a transient error would be routed into a
382		// destructive delete of the wrong ref.
383		target, probeStderr, probeErr := s.runGit("symbolic-ref", "-q", "--end-of-options", name.String())
384		switch {
385		case probeErr == nil && target != "":
386			if _, stderr, delErr := s.runGit("symbolic-ref", "-d", "--end-of-options", name.String()); delErr != nil {
387				return fmt.Errorf("reftable remove symbolic ref %s: %s: %w", name, strings.TrimSpace(string(stderr)), delErr)
388			}
389			return nil
390		case probeErr != nil && !refLookupAbsent(probeErr, probeStderr):
391			return fmt.Errorf("reftable probe symbolic ref %s: %s: %w", name, strings.TrimSpace(string(probeStderr)), probeErr)
392		}
393	
394		// name is not a symbolic ref (or does not exist): delete it as a hash ref.
395		_, stderr, err := s.runGit("update-ref", "-d", "--end-of-options", name.String())
396		if err == nil {
397			return nil
398		}
399		// git update-ref exits 0 when deleting an already-absent ref, so reaching
400		// here means the delete actually failed. Only an explicit "does not exist"
401		// is idempotent success; an empty stderr must NOT be swallowed, because a
402		// killed/timed-out git also produces no stderr and would otherwise be
403		// silently reported as a successful deletion.
404		msg := strings.ToLower(strings.TrimSpace(string(stderr)))
405		if strings.Contains(msg, "does not exist") || strings.Contains(msg, "not exist") {
406			return nil
407		}
408		return fmt.Errorf("reftable remove ref %s: %s: %w", name, strings.TrimSpace(string(stderr)), err)
409	}
410	
411	// CountLooseRefs returns 0: reftable has no loose refs, and go-git only uses
412	// this count to decide whether to pack loose refs, which is a no-op here.
413	func (s *reftableStorer) CountLooseRefs() (int, error) {
414		return 0, nil
415	}
416	
417	// PackRefs is a no-op: the reftable backend maintains its own compaction, so
418	// there is nothing for go-git to pack.
419	func (s *reftableStorer) PackRefs() error {
420		return nil
421	}

