114		}
115		if !info.Mode().IsRegular() {
116			return "", fmt.Errorf("commondir entry at %s is not a regular file", commonFile)
117		}
118	
119		content, err := os.ReadFile(commonFile) //nolint:gosec // path is inside the validated per-worktree Git directory.
120		if err != nil {
121			return "", fmt.Errorf("read commondir file at %s: %w", commonFile, err)
122		}
123		pointer := strings.TrimRight(string(content), "\r\n")
124		if pointer == "" {
