135	func resolveWorktreeID(gitDirPath, commonDir string) (string, error) {
136		same, err := metadataDirectoriesIdentifySameFile(gitDirPath, commonDir)
137		if err != nil {
138			return "", fmt.Errorf("compare Git and common directories: %w", err)
139		}
140		if same {
141			return "", nil
142		}
143	
144		registrationRoot := filepath.Join(commonDir, "worktrees")
145		registrationPath := gitDirPath
146		same, err = metadataDirectoriesIdentifySameFile(filepath.Dir(registrationPath), registrationRoot)
147		if err != nil {
148			return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
149		}
150		if !same {
151			registrationPath, err = filepath.EvalSymlinks(gitDirPath)
152			if err != nil {
153				return "", fmt.Errorf("resolve linked-worktree registration %s: %w", gitDirPath, err)
154			}
155			same, err = metadataDirectoriesIdentifySameFile(filepath.Dir(registrationPath), registrationRoot)
156			if err != nil {
157				return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
158			}
159			if !same {
160				return "", fmt.Errorf("git directory %s is not an immediate child of %s", gitDirPath, registrationRoot)
161			}
162		}
163	
164		id := filepath.Base(registrationPath)
165		if id == "." || id == string(filepath.Separator) || id == "" {
166			return "", fmt.Errorf("git directory %s has no worktree registration name", gitDirPath)
167		}
168		return id, nil
169	}
