171	// Preserve the pointer spelling until validation so a missing component cannot
172	// disappear through lexical cleaning before the filesystem sees it.
173	func resolveMetadataPath(base, value string) string {
174		if filepath.IsAbs(value) {
175			return value
176		}
177		return base + string(filepath.Separator) + value
178	}
