180	func resolveMetadataDirectory(label, base, value string) (string, error) {
181		resolved := resolveMetadataPath(base, value)
182		if err := requireMetadataDirectory(label, resolved); err != nil {
183			return "", err
184		}
185	
186		cleaned := filepath.Clean(resolved)
187		if cleaned == resolved {
188			return cleaned, nil
189		}
190		// Cleaning a path through a symlink before resolving ".." can change which
191		// directory it names, so keep the lexical result only when identity agrees.
192		if same, err := metadataDirectoriesIdentifySameFile(resolved, cleaned); err == nil && same {
193			return cleaned, nil
194		}
195	
196		physical, err := filepath.EvalSymlinks(resolved)
197		if err != nil {
198			return "", fmt.Errorf("resolve %s at %s: %w", label, resolved, err)
199		}
200		return filepath.Clean(physical), nil
201	}
