203	func requireMetadataDirectory(label, path string) error {
204		info, err := os.Stat(path) //nolint:gosec // the explicit-root API resolves caller-selected repository metadata.
205		if err != nil {
206			return fmt.Errorf("inspect %s at %s: %w", label, path, err)
207		}
208		if !info.IsDir() {
209			return fmt.Errorf("%s at %s is not a directory", label, path)
210		}
211		return nil
212	}
213	
214	func metadataDirectoriesIdentifySameFile(a, b string) (bool, error) {
215		aInfo, err := os.Stat(a) //nolint:gosec // explicit-root metadata paths are validated before identity comparison.
216		if err != nil {
217			return false, fmt.Errorf("inspect %s: %w", a, err)
218		}
219		if !aInfo.IsDir() {
220			return false, fmt.Errorf("%s is not a directory", a)
221		}
222		bInfo, err := os.Stat(b)
223		if err != nil {
224			return false, fmt.Errorf("inspect %s: %w", b, err)
225		}
226		if !bInfo.IsDir() {
227			return false, fmt.Errorf("%s is not a directory", b)
228		}
229		return os.SameFile(aInfo, bInfo), nil
230	}
