141	func openBareRepository(repoRoot string) (*git.Repository, error) {
142		repo, err := git.PlainOpen(repoRoot)
143		if err != nil {
144			return nil, fmt.Errorf("failed to open repository: %w", err)
145		}
146		config, err := repo.Config()
147		if err != nil {
148			_ = repo.Close()
149			return nil, fmt.Errorf("validate bare repository config: %w", err)
150		}
151		if !config.Core.IsBare {
152			_ = repo.Close()
153			return nil, fmt.Errorf("path %s has no worktree metadata and is not a bare repository", repoRoot)
154		}
155		return repo, nil
156	}
