   203	func requireMetadataDirectory(label, path string) error {
   204		info, err := os.Stat(path) //nolint:gosec // the explicit-root API resolves caller-selected repository metadata.
   205		if err != nil {
   206			return fmt.Errorf("inspect %s at %s: %w", label, path, err)
   207		}
   208		if !info.IsDir() {
   209			return fmt.Errorf("%s at %s is not a directory", label, path)
   210		}
   211		return nil
   212	}
