	assertGuardLedgerSeen(t, "--git-common-dir query", allowedCommonDirQueries, commonDirQueriesSeen)
	assertGuardLedgerSeen(t, "legacy resolver call", allowedLegacyResolverCalls, legacyResolverCallsSeen)
}

