 40			"trail_checkout_worktree.go:gitCommonDirForTrailWorktree":   "trail storage paths migrate with the remaining consumers",
 41			"trail_checkout_worktree.go:validateTrailWorktreeReuse":     "trail reuse validation migrates with the remaining consumers",
 42		}
 43		allowedLegacyResolverCalls := map[string]string{
 44			"agent/codex/hook_root.go:resolveHookDiscovery": "Codex discovery migrates with the remaining consumers",
 45			"agent/codex/hook_root.go:rootOwnsGitDir":       "Codex ownership policy migrates with the remaining consumers",
 46		}
 47	
 48		_, thisFile, _, ok := runtime.Caller(0)
 49		if !ok {
 50			t.Fatal("resolve guard source path")
 51		}
 52		cliRoot := filepath.Dir(filepath.Dir(thisFile))
 53		fset := token.NewFileSet()
 54		canonicalTokens := 0
 55		legacyOwnersSeen := map[string]bool{}
 56		policyInspectionsSeen := map[string]bool{}
 57		commonDirQueriesSeen := map[string]bool{}
 58		legacyResolverCallsSeen := map[string]bool{}
 59	
 60		err := filepath.WalkDir(cliRoot, func(path string, entry fs.DirEntry, walkErr error) error {
 61			if walkErr != nil {
 62				return walkErr
 63			}
 64			if entry.IsDir() {
 65				return nil
 66			}
 67			rel, err := filepath.Rel(cliRoot, path)
 68			if err != nil {
 69				return err
 70			}
 71			rel = filepath.ToSlash(rel)
 72			if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") ||
 73				strings.HasPrefix(rel, "integration_test/") || strings.HasPrefix(rel, "benchutil/") {
 74				return nil
 75			}
 76	
 77			file, err := parser.ParseFile(fset, path, nil, 0)
 78			if err != nil {
 79				return err
 80			}
 81			dotGitIdentifiers := metadataStringIdentifiers(file, ".git")
 82			dotGitIdentifiers["gitDir"] = true
 83			gitrepoImports, dotImportedGitrepo := gitrepoImportNames(file)
 84			filesystemImports := filesystemImportNames(file)
 85			for _, decl := range file.Decls {
 86				fn, ok := decl.(*ast.FuncDecl)
 87				if !ok || fn.Body == nil {
 88					continue
 89				}
 90				key := rel + ":" + fn.Name.Name
 91				canonicalOwner := rel == "gitrepo/metadata.go"
 92				_, legacyOwner := legacyTraversalOwners[key]
 93				_, policyInspection := policyDotGitInspections[key]
 94	
 95				hasDotGitReference := containsMetadataString(fn.Body, ".git") || containsAnyIdentifier(fn.Body, dotGitIdentifiers)
 96				ast.Inspect(fn.Body, func(node ast.Node) bool {
 97					switch n := node.(type) {
 98					case *ast.BasicLit:
 99						if n.Kind != token.STRING {
100							return true
101						}
102						value, unquoteErr := strconv.Unquote(n.Value)
103						if unquoteErr != nil {
104							return true
105						}
106						if value == "--git-common-dir" {
107							if _, allowed := allowedCommonDirQueries[key]; allowed {
108								commonDirQueriesSeen[key] = true
109							} else {
110								t.Errorf("%s runs an unaudited --git-common-dir query; use gitrepo.ResolveWorktreeMetadata or document a semantic-query exception", fset.Position(n.Pos()))
111							}
112						}
113						if value != "gitdir: " && value != "gitdir:" && value != "commondir" {
114							return true
115						}
116						if canonicalOwner {
117							canonicalTokens++
118							return true
119						}
120						if legacyOwner {
121							legacyOwnersSeen[key] = true
122						} else {
123							t.Errorf("%s independently parses Git metadata token %q; use gitrepo.ResolveWorktreeMetadata", fset.Position(n.Pos()), value)
124						}
125					case *ast.CallExpr:
126						if isLegacyMetadataResolverCall(n, gitrepoImports, dotImportedGitrepo) {
127							if _, allowed := allowedLegacyResolverCalls[key]; allowed {
128								legacyResolverCallsSeen[key] = true
129							} else {
130								t.Errorf("%s calls a legacy Git metadata resolver; use gitrepo.ResolveWorktreeMetadata or document the migration exception", fset.Position(n.Pos()))
131							}
132						}
133						callHasDotGitReference := containsMetadataString(n, ".git") || containsAnyIdentifier(n, dotGitIdentifiers)
134						packageInspection := hasDotGitReference && isPackageFilesystemInspection(n, filesystemImports)
135						if (!callHasDotGitReference && !packageInspection) || !isFilesystemMetadataInspection(n) || canonicalOwner {
136							return true
137						}
138						if legacyOwner {
139							legacyOwnersSeen[key] = true
140							return true
141						}
142						if policyInspection {
143							policyInspectionsSeen[key] = true
144							return true
145						}
146						t.Errorf("%s independently inspects a .git entry; use gitrepo.ResolveWorktreeMetadata or document a narrow policy exception", fset.Position(n.Pos()))
147					}
148					return true
149				})
150			}
151			return nil
152		})
153		if err != nil {
154			t.Fatalf("scan Go sources: %v", err)
155		}
156		if canonicalTokens < 2 {
157			t.Fatal("guard found no canonical gitdir/commondir parser tokens")
158		}
159		assertGuardLedgerSeen(t, "legacy traversal owner", legacyTraversalOwners, legacyOwnersSeen)
160		assertGuardLedgerSeen(t, ".git policy inspection", policyDotGitInspections, policyInspectionsSeen)
161		assertGuardLedgerSeen(t, "--git-common-dir query", allowedCommonDirQueries, commonDirQueriesSeen)
162		assertGuardLedgerSeen(t, "legacy resolver call", allowedLegacyResolverCalls, legacyResolverCallsSeen)
163	}
