165	func TestGitMetadataGuardRecognizesBypassForms(t *testing.T) {
166		t.Parallel()
167	
168		tests := []struct {
169			name       string
170			source     string
171			wantLegacy bool
172		}{
173			{
174				name:   "rooted filesystem",
175				source: `package probe; import "os"; func inspect(root *os.Root) { _, _ = root.Lstat(".git") }`,
176			},
177			{
178				name:   "package constant",
179				source: `package probe; import "os"; const dotGitName = ".git"; func inspect() { _, _ = os.Stat(dotGitName) }`,
180			},
181			{
182				name:   "readlink",
183				source: `package probe; import "os"; func inspect() { _, _ = os.Readlink(".git") }`,
184			},
185			{
186				name:       "aliased legacy resolver import",
187				source:     `package probe; import repo "github.com/entireio/cli/cmd/entire/cli/gitrepo"; func inspect() { _, _ = repo.ResolveDotGitPath(".") }`,
188				wantLegacy: true,
189			},
190		}
191	
192		for _, tt := range tests {
193			t.Run(tt.name, func(t *testing.T) {
194				t.Parallel()
195				fset := token.NewFileSet()
196				file, err := parser.ParseFile(fset, "probe.go", tt.source, 0)
197				if err != nil {
198					t.Fatalf("parse probe: %v", err)
199				}
200				identifiers := metadataStringIdentifiers(file, ".git")
201				identifiers["gitDir"] = true
202				imports, dotImported := gitrepoImportNames(file)
203				found := false
204				for _, decl := range file.Decls {
205					fn, ok := decl.(*ast.FuncDecl)
206					if !ok || fn.Body == nil {
207						continue
208					}
209					hasDotGitReference := containsMetadataString(fn.Body, ".git") || containsAnyIdentifier(fn.Body, identifiers)
210					ast.Inspect(fn.Body, func(node ast.Node) bool {
211						call, ok := node.(*ast.CallExpr)
212						if !ok {
213							return true
214						}
215						if tt.wantLegacy {
216							found = found || isLegacyMetadataResolverCall(call, imports, dotImported)
217						} else {
218							found = found || hasDotGitReference && isFilesystemMetadataInspection(call)
219						}
220						return true
221					})
222				}
223				if !found {
224					t.Fatal("guard did not recognize probe")
225				}
226			})
227		}
228	}
229	
230	func isFilesystemMetadataInspection(call *ast.CallExpr) bool {
231		selector, ok := call.Fun.(*ast.SelectorExpr)
232		if !ok {
233			return false
234		}
235		switch selector.Sel.Name {
236		case "Lstat", "Open", "OpenFile", "ReadDir", "ReadFile", "Readlink", "Stat":
237			return true
238		default:
239			return false
240		}
241	}
242	
243	func metadataStringIdentifiers(file *ast.File, want string) map[string]bool {
244		identifiers := map[string]bool{}
245		for _, decl := range file.Decls {
246			gen, ok := decl.(*ast.GenDecl)
247			if !ok {
248				continue
249			}
250			for _, spec := range gen.Specs {
251				valueSpec, ok := spec.(*ast.ValueSpec)
252				if !ok {
253					continue
254				}
255				for i, value := range valueSpec.Values {
256					literal, ok := value.(*ast.BasicLit)
257					if !ok || literal.Kind != token.STRING {
258						continue
259					}
260					unquoted, err := strconv.Unquote(literal.Value)
261					if err == nil && unquoted == want && i < len(valueSpec.Names) {
262						identifiers[valueSpec.Names[i].Name] = true
263					}
264				}
265			}
266		}
267		return identifiers
268	}
269	
270	func gitrepoImportNames(file *ast.File) (map[string]bool, bool) {
271		names := map[string]bool{}
272		dotImported := false
273		for _, spec := range file.Imports {
274			path, err := strconv.Unquote(spec.Path.Value)
275			if err != nil || path != "github.com/entireio/cli/cmd/entire/cli/gitrepo" {
276				continue
277			}
278			switch {
279			case spec.Name == nil:
280				names["gitrepo"] = true
281			case spec.Name.Name == ".":
282				dotImported = true
283			case spec.Name.Name != "_":
284				names[spec.Name.Name] = true
285			}
286		}
287		return names, dotImported
288	}
289	
290	func filesystemImportNames(file *ast.File) map[string]bool {
291		names := map[string]bool{}
292		for _, spec := range file.Imports {
293			path, err := strconv.Unquote(spec.Path.Value)
294			if err != nil || (path != "os" && path != "io/fs") || (spec.Name != nil && spec.Name.Name == "_") {
295				continue
296			}
297			switch {
298			case spec.Name == nil:
299				names[filepath.Base(path)] = true
300			case spec.Name.Name != ".":
301				names[spec.Name.Name] = true
302			}
303		}
304		return names
305	}
306	
307	func isPackageFilesystemInspection(call *ast.CallExpr, importNames map[string]bool) bool {
308		selector, ok := call.Fun.(*ast.SelectorExpr)
309		if !ok {
310			return false
311		}
312		pkg, ok := selector.X.(*ast.Ident)
313		return ok && importNames[pkg.Name]
314	}
315	
316	func isLegacyMetadataResolverCall(call *ast.CallExpr, importNames map[string]bool, dotImported bool) bool {
317		legacyName := func(name string) bool {
318			return name == "ResolveDotGitPath" || name == "ResolveCommonGitPath"
319		}
320		if ident, ok := call.Fun.(*ast.Ident); ok {
321			return dotImported && legacyName(ident.Name)
322		}
323		selector, ok := call.Fun.(*ast.SelectorExpr)
324		if !ok || !legacyName(selector.Sel.Name) {
325			return false
326		}
327		pkg, ok := selector.X.(*ast.Ident)
328		return ok && importNames[pkg.Name]
329	}
330	
331	func assertGuardLedgerSeen(t *testing.T, label string, ledger map[string]string, seen map[string]bool) {
332		t.Helper()
333		for key, reason := range ledger {
334			if !seen[key] {
335				t.Errorf("documented %s %s (%s) no longer exists; remove or update the exception", label, key, reason)
336			}
337		}
338	}
339	
340	func containsMetadataString(node ast.Node, want string) bool {
341		found := false
342		ast.Inspect(node, func(n ast.Node) bool {
343			literal, ok := n.(*ast.BasicLit)
344			if !ok || literal.Kind != token.STRING {
345				return true
346			}
347			value, err := strconv.Unquote(literal.Value)
348			if err == nil && value == want {
349				found = true
350				return false
351			}
352			return true
353		})
354		return found
355	}
356	
357	func containsAnyIdentifier(node ast.Node, want map[string]bool) bool {
358		found := false
359		ast.Inspect(node, func(n ast.Node) bool {
360			ident, ok := n.(*ast.Ident)
361			if ok && want[ident.Name] {
362				found = true
363				return false
364			}
365			return true
366		})
367		return found
368	}

