func TestExplainEmptyManifest_BaseCommitMismatch(t *testing.T) {
	t.Parallel()
	started := time.Now()
	summary := reviewtypes.RunSummary{
		StartedAt: started,
		AgentRuns: []reviewtypes.AgentRun{{Name: "claude-code"}},
	}
