		},
	}
	cmd.Flags().StringVarP(&message, "message", "m", "", "Optional approval comment")
	cmd.Flags().StringVar(&branch, "branch", "", "Branch of the trail (defaults to current); cannot be combined with a trail selector")
	return cmd
}
