   360	func gitrepoImportNames(file *ast.File) (map[string]bool, bool) {
   361		names := map[string]bool{}
   362		dotImported := false
   363		for _, spec := range file.Imports {
   364			path, err := strconv.Unquote(spec.Path.Value)
   365			if err != nil || path != "github.com/entireio/cli/cmd/entire/cli/gitrepo" {
   366				continue
   367			}
   368			switch {
   369			case spec.Name == nil:
   370				names["gitrepo"] = true
   371			case spec.Name.Name == ".":
   372				dotImported = true
   373			case spec.Name.Name != "_":
   374				names[spec.Name.Name] = true
   375			}
   376		}
   377		return names, dotImported
   378	}
