   404	type guardValueResolver struct {
   405		packageValues map[string]string
   406		typeInfo      *types.Info
   407		bindings      map[types.Object]ast.Expr
   408	}
   409	
   410	func newGuardValueResolver(fset *token.FileSet, file *ast.File, packageValues map[string]string) guardValueResolver {
   411		typeInfo := &types.Info{
   412			Defs: map[*ast.Ident]types.Object{},
   413			Uses: map[*ast.Ident]types.Object{},
   414		}
   415		config := types.Config{Error: func(error) {}}
   416		_, typeErr := config.Check(file.Name.Name, fset, []*ast.File{file}, typeInfo)
   417		// Files are checked in isolation, so unresolved cross-file imports are
   418		// expected; local definitions collected before that error remain usable.
   419		if typeErr != nil && len(typeInfo.Defs) == 0 && len(typeInfo.Uses) == 0 {
   420			return guardValueResolver{packageValues: packageValues, typeInfo: typeInfo}
   421		}
   422		return guardValueResolver{
   423			packageValues: packageValues,
   424			typeInfo:      typeInfo,
   425			bindings:      guardValueBindings(file, typeInfo),
   426		}
   427	}
   428	
   429	func guardValueBindings(file *ast.File, typeInfo *types.Info) map[types.Object]ast.Expr {
   430		bindings := map[types.Object]ast.Expr{}
   431		ast.Inspect(file, func(node ast.Node) bool {
   432			switch decl := node.(type) {
   433			case *ast.ValueSpec:
   434				for i, name := range decl.Names {
   435					if object := typeInfo.Defs[name]; object != nil {
   436						bindings[object] = expressionAt(decl.Values, i)
   437					}
   438				}
   439			case *ast.AssignStmt:
   440				if decl.Tok != token.DEFINE {
   441					return true
   442				}
   443				for i, lhs := range decl.Lhs {
   444					name, ok := lhs.(*ast.Ident)
   445					if !ok {
   446						continue
   447					}
   448					if object := typeInfo.Defs[name]; object != nil {
   449						bindings[object] = expressionAt(decl.Rhs, i)
   450					}
   451				}
   452			}
   453			return true
   454		})
   455		return bindings
   456	}
   457	
   458	func expressionAt(expressions []ast.Expr, index int) ast.Expr {
   459		if index < len(expressions) {
   460			return expressions[index]
   461		}
   462		if len(expressions) == 1 {
   463			return expressions[0]
   464		}
   465		return nil
   466	}
