   409	
   410	func newGuardValueResolver(fset *token.FileSet, file *ast.File, packageValues map[string]string) guardValueResolver {
   411		typeInfo := &types.Info{
   412			Defs: map[*ast.Ident]types.Object{},
   413			Uses: map[*ast.Ident]types.Object{},
   414		}
   415		config := types.Config{Error: func(error) {}}
   416		_, typeErr := config.Check(file.Name.Name, fset, []*ast.File{file}, typeInfo)
   417		// Files are checked in isolation, so unresolved cross-file imports are
   418		// expected; local definitions collected before that error remain usable.
   419		if typeErr != nil && len(typeInfo.Defs) == 0 && len(typeInfo.Uses) == 0 {
   420			return guardValueResolver{packageValues: packageValues, typeInfo: typeInfo}
   421		}
   422		return guardValueResolver{
   423			packageValues: packageValues,
   424			typeInfo:      typeInfo,
   425			bindings:      guardValueBindings(file, typeInfo),
   426		}
   427	}
