   109					}
   110					if legacyOwner {
   111						legacyOwnersSeen[key] = true
   112						continue
   113					}
   114					t.Errorf("%s independently parses Git metadata token %q; use gitrepo.ResolveWorktreeMetadata", fset.Position(fn.Pos()), value)
   115				}
