   134						if _, allowed := allowedLegacyResolverCalls[key]; allowed {
   135							legacyResolverCallsSeen[key] = true
   136						} else {
   137							t.Errorf("%s calls a legacy Git metadata resolver; use gitrepo.ResolveWorktreeMetadata or document the migration exception", fset.Position(call.Pos()))
   138						}
   139					}
   140					if !valueResolver.contains(call, ".git") || !isFilesystemMetadataInspection(call) || canonicalOwner {
   141						return true
   142					}
   143					if legacyOwner {
   144						legacyOwnersSeen[key] = true
   145						return true
   146					}
   147					if policyInspection {
   148						policyInspectionsSeen[key] = true
   149						return true
   150					}
   151					t.Errorf("%s independently inspects a .git entry; use gitrepo.ResolveWorktreeMetadata or document a narrow policy exception", fset.Position(call.Pos()))
   152					return true
   153				})
   154			}
   155			return nil
   156		})
