   169	func TestGitMetadataGuardRecognizesBypassForms(t *testing.T) {
   170		t.Parallel()
   171	
   172		tests := []struct {
   173			name        string
   174			source      string
   175			kind        string
   176			value       string
   177			samePackage bool
   178			want        bool
   179		}{
   180			{
   181				name:   "rooted filesystem with local alias",
   182				source: `package probe; import "os"; func inspect(root *os.Root) { name := ".git"; _, _ = root.Lstat(name) }`,
   183				kind:   "filesystem",
   184				want:   true,
   185			},
   186			{
   187				name:   "package constant",
   188				source: `package probe; import "os"; const dotGitName = ".git"; func inspect() { _, _ = os.Stat(dotGitName) }`,
   189				kind:   "filesystem",
   190				want:   true,
   191			},
   192			{
   193				name:   "open root",
   194				source: `package probe; import "os"; func inspect() { _, _ = os.OpenRoot(".git") }`,
   195				kind:   "filesystem",
   196				want:   true,
   197			},
   198			{
   199				name:   "package parser token",
   200				source: `package probe; import "strings"; const prefix = "gitdir: "; func inspect(data string) { _, _ = strings.CutPrefix(data, prefix) }`,
   201				kind:   "token",
   202				value:  "gitdir: ",
   203				want:   true,
   204			},
   205			{
   206				name:   "absolute git directory query",
   207				source: `package probe; import "os/exec"; const flag = "--absolute-git-dir"; func inspect() { _ = exec.Command("git", "rev-parse", flag) }`,
   208				kind:   "query",
   209				value:  "--absolute-git-dir",
   210				want:   true,
   211			},
   212			{
   213				name:   "aliased legacy resolver import",
   214				source: `package probe; import repo "github.com/entireio/cli/cmd/entire/cli/gitrepo"; func inspect() { _, _ = repo.ResolveDotGitPath(".") }`,
   215				kind:   "legacy",
   216				want:   true,
   217			},
   218			{
   219				name:        "same-package legacy resolver",
   220				source:      `package gitrepo; func inspect() { _, _ = ResolveDotGitPath(".") }`,
   221				kind:        "legacy",
   222				samePackage: true,
   223				want:        true,
   224			},
   225			{
   226				name:   "git directory parameter is not metadata traversal",
   227				source: `package probe; import "os"; func inspect(gitDir string) { _, _ = os.Stat(gitDir) }`,
   228				kind:   "filesystem",
   229				want:   false,
   230			},
   231		}
   232	
   233		for _, tt := range tests {
   234			t.Run(tt.name, func(t *testing.T) {
   235				t.Parallel()
   236				fset := token.NewFileSet()
   237				file, err := parser.ParseFile(fset, "probe.go", tt.source, 0)
   238				if err != nil {
   239					t.Fatalf("parse probe: %v", err)
   240				}
   241				values := packageStringValues(file)
   242				valueResolver := newGuardValueResolver(fset, file, values)
   243				imports, dotImported := gitrepoImportNames(file)
   244				found := false
   245				for _, decl := range file.Decls {
   246					fn, ok := decl.(*ast.FuncDecl)
   247					if !ok || fn.Body == nil {
   248						continue
   249					}
   250					switch tt.kind {
   251					case "token":
   252						found = valueResolver.contains(fn.Body, tt.value)
   253					case "query":
   254						found = valueResolver.contains(fn.Body, "rev-parse") &&
   255							valueResolver.contains(fn.Body, tt.value)
   256					}
   257					ast.Inspect(fn.Body, func(node ast.Node) bool {
   258						call, ok := node.(*ast.CallExpr)
   259						if !ok {
   260							return true
   261						}
   262						switch tt.kind {
   263						case "legacy":
   264							found = found || isLegacyMetadataResolverCall(call, imports, dotImported, tt.samePackage)
   265						case "filesystem":
   266							found = found || valueResolver.contains(call, ".git") && isFilesystemMetadataInspection(call)
   267						}
   268						return true
   269					})
   270				}
   271				if found != tt.want {
   272					t.Fatalf("guard recognition = %t, want %t", found, tt.want)
   273				}
   274			})
   275		}
   276	}
