   299	func collectGuardPackageStringValues(repoRoot string) (map[string]map[string]string, error) {
   300		values := map[string]map[string]string{}
   301		fset := token.NewFileSet()
   302		err := filepath.WalkDir(repoRoot, func(path string, entry fs.DirEntry, walkErr error) error {
   303			if walkErr != nil {
   304				return walkErr
   305			}
   306			if entry.IsDir() {
   307				return nil
   308			}
   309			rel, err := filepath.Rel(repoRoot, path)
   310			if err != nil {
   311				return err
   312			}
   313			rel = filepath.ToSlash(rel)
   314			if !isGuardSourceFile(rel) {
   315				return nil
   316			}
   317			file, err := parser.ParseFile(fset, path, nil, 0)
   318			if err != nil {
   319				return err
   320			}
   321			key := guardPackageKey(rel, file)
   322			if values[key] == nil {
   323				values[key] = map[string]string{}
   324			}
   325			for name, value := range packageStringValues(file) {
   326				values[key][name] = value
   327			}
   328			return nil
   329		})
   330		return values, err
   331	}
