+	if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
+		return false
+	}
+	for _, prefix := range []string{
+		"cmd/entire/cli/agent/testutil/",
+		"cmd/entire/cli/benchutil/",
+		"cmd/entire/cli/integration_test/",
+		"e2e/",
+	} {
+		if strings.HasPrefix(rel, prefix) {
+			return false
+		}
+	}
+	return true
+}
